-- Phase 14 Project naming: the additive StudyJourneyProject.displayName column plus
-- the enum CHECK rebuilds required to audit the new project_rename operation and
-- project_renamed event. Nothing is deleted, retyped or backfilled; legacy Projects
-- keep displayName = NULL and the existing localized date + short-ID label. The three
-- document worker operations stay service-only: they are NEVER authorized for a user
-- actor, exactly as in the previous constraint.
ALTER TABLE "StudyJourneyProject" ADD COLUMN "displayName" varchar(100);--> statement-breakpoint
ALTER TABLE "StudyJourneyProject" ADD CONSTRAINT "StudyJourneyProject_display_name_check" CHECK ("displayName" is null or (char_length("displayName") between 1 and 100 and "displayName" = btrim("displayName") and "displayName" !~ '[[:cntrl:]]'));--> statement-breakpoint
ALTER TABLE "ProjectOperation" DROP CONSTRAINT "ProjectOperation_type_check";--> statement-breakpoint
ALTER TABLE "ProjectOperation" ADD CONSTRAINT "ProjectOperation_type_check" CHECK ("operationType" IN ('project_create','project_close','membership_invite','membership_accept','membership_revoke','project_chat_create','project_document_upload_intent','project_document_import_intent','project_document_storage_finalize','project_document_storage_fail','project_document_scan_finalize','project_document_grant_create','project_document_grant_revoke','project_document_withdraw','project_requirement_state_change','project_evidence_extract','project_fact_mutation','project_staff_assignment_propose','project_staff_assignment_owner_approve','project_staff_assignment_owner_decline','project_staff_assignment_lawyer_accept','project_staff_assignment_lawyer_decline','project_staff_assignment_owner_revoke','project_staff_assignment_lawyer_resign','project_staff_assignment_admin_withdraw','project_staff_assignment_admin_revoke','project_thread_participation_consent_create','project_thread_participation_consent_withdraw','project_human_message_send','service_engagement_create','service_engagement_agreement_draft','service_engagement_agreement_issue','service_engagement_agreement_accept','service_engagement_signature_submit','service_engagement_signature_verify','service_engagement_activate','service_engagement_suspend','service_engagement_resume','service_engagement_terminate','project_resource_disclosure_grant_create','project_resource_disclosure_grant_revoke','service_payment_condition_record','service_payment_evidence_submit','service_payment_evidence_verify','service_payment_resolution_record','project_rename'));--> statement-breakpoint
ALTER TABLE "ProjectOperation" DROP CONSTRAINT "ProjectOperation_actor_type_check";--> statement-breakpoint
ALTER TABLE "ProjectOperation" ADD CONSTRAINT "ProjectOperation_actor_type_check" CHECK (("operationType" IN ('project_create','project_close','membership_invite','membership_accept','membership_revoke','project_chat_create','project_document_upload_intent','project_document_import_intent','project_document_grant_create','project_document_grant_revoke','project_document_withdraw','project_requirement_state_change','project_evidence_extract','project_fact_mutation','project_staff_assignment_propose','project_staff_assignment_owner_approve','project_staff_assignment_owner_decline','project_staff_assignment_lawyer_accept','project_staff_assignment_lawyer_decline','project_staff_assignment_owner_revoke','project_staff_assignment_lawyer_resign','project_staff_assignment_admin_withdraw','project_staff_assignment_admin_revoke','project_thread_participation_consent_create','project_thread_participation_consent_withdraw','project_human_message_send','service_engagement_create','service_engagement_agreement_draft','service_engagement_agreement_issue','service_engagement_agreement_accept','service_engagement_signature_submit','service_engagement_signature_verify','service_engagement_activate','service_engagement_suspend','service_engagement_resume','service_engagement_terminate','project_resource_disclosure_grant_create','project_resource_disclosure_grant_revoke','service_payment_condition_record','service_payment_evidence_submit','service_payment_evidence_verify','service_payment_resolution_record','project_rename') AND "actorKind" = 'user') OR ("operationType" IN ('project_document_storage_finalize','project_document_storage_fail') AND "actorKind" = 'service' AND "servicePrincipalCode" = 'project_document_storage_worker' AND "operationId" ~ '^[0-9a-f]{64}$') OR ("operationType" = 'project_document_scan_finalize' AND "actorKind" = 'service' AND "servicePrincipalCode" = 'project_document_scan_worker' AND "operationId" ~ '^[0-9a-f]{64}$'));--> statement-breakpoint
ALTER TABLE "ProjectEvent" DROP CONSTRAINT "ProjectEvent_type_check";--> statement-breakpoint
ALTER TABLE "ProjectEvent" ADD CONSTRAINT "ProjectEvent_type_check" CHECK ("eventType" IN ('project_created','membership_state_changed','project_chat_created','project_closed','project_document_intent_created','project_document_storage_changed','project_document_security_changed','project_document_grant_changed','project_document_withdrawn','project_requirement_state_changed','project_evidence_extraction_completed','project_fact_changed','project_staff_assignment_proposed','project_staff_assignment_owner_approved','project_staff_assignment_owner_declined','project_staff_assignment_lawyer_accepted','project_staff_assignment_lawyer_declined','project_staff_assignment_owner_revoked','project_staff_assignment_lawyer_resigned','project_staff_assignment_admin_withdrawn','project_staff_assignment_admin_revoked','project_thread_participation_consent_created','project_thread_participation_consent_withdrawn','service_engagement_created','service_engagement_agreement_version_drafted','service_engagement_agreement_version_issued','service_engagement_agreement_accepted','service_engagement_signature_evidence_recorded','service_engagement_signature_evidence_verified','service_engagement_signature_evidence_rejected','service_engagement_activated','service_engagement_suspended','service_engagement_resumed','service_engagement_terminated','project_resource_disclosure_granted','project_resource_disclosure_revoked','service_payment_condition_recorded','service_payment_evidence_recorded','service_payment_evidence_verified','service_payment_evidence_rejected','service_payment_resolution_recorded','project_renamed'));
